// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/summary", wrapper.GetSummary)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/scope", wrapper.GetScope)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/exposure", wrapper.GetExposure)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/findings", wrapper.ListFindings)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/transitions", wrapper.ListTransitions)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/advisories/{id}", wrapper.GetAdvisory)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/workloads", wrapper.ListWorkloads)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/workloads/{kind}/{namespace}/{name}", wrapper.GetWorkload)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/images", wrapper.ListImages)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/images/{digest}", wrapper.GetImage)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/images/{digest}/packages", wrapper.ListImagePackages)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/packages", wrapper.ListPackages)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/nodegroups", wrapper.ListNodeGroups)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/nodegroups/{id}", wrapper.GetNodeGroup)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/nodes/{name}", wrapper.GetNode)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/coverage", wrapper.GetCoverage)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/feeds", wrapper.ListFeeds)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/exceptions", wrapper.ListExceptions)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/settings", wrapper.GetSettings)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/search", wrapper.Search)

	return m
}

